<?php require_once __DIR__.'/initiative-common.php';$uid=initiativeUserId();$id=(int)($_GET['id']??$_POST['initiative_id']??0);$i=initiativeLoad($id);if(!initiativeCanEdit($i,$uid)){http_response_code(403);exit('Not editable.');}$db=initiativeDb();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){initiativeVerifyCsrf();try{$db->beginTransaction();$s=$db->prepare("UPDATE initiatives SET title=:title,description=:description,objectives=:objectives,initiative_type=:type,expected_budget=NULLIF(:budget,'')::numeric,planned_start_date=NULLIF(:start,'')::date,planned_end_date=NULLIF(:end,'')::date,updated_at=CURRENT_TIMESTAMP WHERE initiative_id=:id");$s->execute(['title'=>trim($_POST['title']??''),'description'=>trim($_POST['description']??''),'objectives'=>trim($_POST['objectives']??''),'type'=>trim($_POST['initiative_type']??''),'budget'=>$_POST['expected_budget']??'','start'=>$_POST['planned_start_date']??'','end'=>$_POST['planned_end_date']??'','id'=>$id]);$i=initiativeLoad($id);$v=$db->prepare("INSERT INTO initiative_versions(initiative_id,version_number,initiative_snapshot,change_summary,created_by) SELECT :id,COALESCE(MAX(version_number),0)+1,CAST(:snap AS jsonb),:summary,:uid FROM initiative_versions WHERE initiative_id=:id");$v->execute(['id'=>$id,'snap'=>initiativeSnapshot($i),'summary'=>trim($_POST['change_summary']??'Updated draft'),'uid'=>$uid]);$db->commit();header('Location: initiative-view.php?id='.$id);exit;}catch(Throwable $e){if($db->inTransaction())$db->rollBack();$error=$e->getMessage();}} initiativeHeader('Edit initiative');?><h1>Edit initiative</h1><?php if($error):?><div class="error"><?=initiativeH($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=initiativeCsrf()?>"><input type="hidden" name="initiative_id" value="<?=$id?>"><label>Title<input name="title" value="<?=initiativeH($i['title'])?>" required></label><label>Type<input name="initiative_type" value="<?=initiativeH($i['initiative_type'])?>" required></label><label>Description<textarea name="description"><?=initiativeH($i['description'])?></textarea></label><label>Objectives<textarea name="objectives"><?=initiativeH($i['objectives'])?></textarea></label><label>Budget<input type="number" step="0.01" min="0" name="expected_budget" value="<?=initiativeH((string)$i['expected_budget'])?>"></label><label>Start<input type="date" name="planned_start_date" value="<?=initiativeH((string)$i['planned_start_date'])?>"></label><label>End<input type="date" name="planned_end_date" value="<?=initiativeH((string)$i['planned_end_date'])?>"></label><label>Change summary<input name="change_summary"></label><button>Save</button></form><?php initiativeFooter();?>
